// components/MonitoringWidget.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip } from "recharts";

const MonitoringWidget = () => {
    const [metrics, setMetrics] = useState([]);

    useEffect(() => {
        axios.get("/api/metrics/").then((response) => {
            setMetrics(response.data.data); // Adjust response structure based on your API
        });
    }, []);

    return (
        <div style={{ border: "1px solid #ccc", padding: "1rem", borderRadius: "8px" }}>
            <h3>Website Metrics</h3>
            <LineChart width={600} height={300} data={metrics}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="timestamp" />
                <YAxis />
                <Tooltip />
                <Line type="monotone" dataKey="cpu_usage" stroke="#8884d8" />
                <Line type="monotone" dataKey="memory_usage" stroke="#82ca9d" />
            </LineChart>
        </div>
    );
};

export default MonitoringWidget;
